export default async (ctx, client) => {
  const conns = await client.connections.list({});
  const rows = (conns?.items ?? conns ?? []).map((c) => ({
    slug: c.slug, connector: c.connector_key,
    device_online: c.device_online, device_id: c.device_id,
    device_last_seen_at: c.device_last_seen_at,
    status: c.status,
  })).filter((r) => r.device_id || r.device_online !== undefined);
  return { org: ctx.organization_id, total: (conns?.items ?? conns ?? []).length, deviceRows: rows.slice(0, 25) };
}

export default async (ctx, client) => {
  const conns = await client.connections.list({});
  return { org: ctx.organization_id, keys: Object.keys(conns || {}), sample: JSON.stringify(conns).slice(0, 1200) };
}

export default async (ctx, client) => {
  const r = await client.connections.list({});
  const now = Date.now();
  const devs = (r.connections || [])
    .filter((c) => c.device_worker_id)
    .map((c) => ({
      slug: c.slug,
      label: c.device_label,
      online: c.device_online,
      status: c.device_status,
      last_seen: c.device_last_seen_at,
      age_sec: c.device_last_seen_at ? Math.round((now - new Date(c.device_last_seen_at).getTime()) / 1000) : null,
    }));
  return { nowIso: new Date(now).toISOString(), count: devs.length, devs };
}

export default async (ctx, client) => {
  const sample = async () => {
    const r = await client.connections.list({});
    const now = Date.now();
    const byDevice = {};
    for (const c of (r.connections || []).filter((x) => x.device_worker_id)) {
      const k = c.device_label;
      if (!byDevice[k] || new Date(c.device_last_seen_at) > new Date(byDevice[k].last_seen)) {
        byDevice[k] = { last_seen: c.device_last_seen_at, online: c.device_online,
          age_sec: Math.round((now - new Date(c.device_last_seen_at).getTime()) / 1000) };
      }
    }
    return byDevice;
  };
  const a = await sample();
  await ctx.sleep(30000);
  const b = await sample();
  const out = {};
  for (const k of Object.keys(a)) {
    out[k] = { before: a[k], after: b[k],
      advanced_sec: Math.round((new Date(b[k].last_seen).getTime() - new Date(a[k].last_seen).getTime()) / 1000) };
  }
  return out;
}

export default async (ctx, client) => {
  const r = await client.connections.list({});
  const c = (r.connections || []).find((x) => x.device_label === "Burak’s MacBook Pro");
  const now = Date.now();
  const deviceFields = {};
  for (const [k, v] of Object.entries(c || {})) if (k.startsWith("device")) deviceFields[k] = v;
  return {
    slug: c?.slug,
    age_sec: Math.round((now - new Date(c.device_last_seen_at).getTime()) / 1000),
    deviceFields,
  };
}

