export default async (ctx, client) => {
  const runs = await client.operations.listRuns({ status: "failed", limit: 40 });
  const list = runs.runs || runs.items || [];
  const hits = list
    .map((r) => ({ id: r.id, key: r.operation_key, status: r.status, created: r.created_at,
                   err: r.error_message || r.error || null }))
    .filter((r) => r.err && /offline|last seen|device/i.test(String(r.err)));
  return { scanned: list.length, hits: hits.slice(0, 8) };
}

export default async (ctx, client) => {
  const exact = await client.knowledge.read({ content_ids: [4821655] });
  const s = JSON.stringify(exact);
  const item = (exact.events || exact.items || exact.content || [])[0] || exact;
  const keys = Object.keys(item || {});
  return {
    len: s.length,
    topKeys: Object.keys(exact),
    itemKeys: keys.filter((k) => /request|status|bytes/i.test(k)),
    hasRequest: /"request"\s*:/.test(s),
    hasRequestBytes: /"request_bytes"\s*:/.test(s),
    hasRequestStatus: /"request_status"\s*:/.test(s),
    statusVal: (s.match(/"request_status"\s*:\s*"([^"]*)"/) || [])[1] || null,
  };
}

export default async (ctx, client) => {
  const out = {};
  try {
    const list = await client.knowledge.search({ origin_types: ["tool_invocation"], limit: 5 });
    const s = JSON.stringify(list);
    out.search = {
      ok: true,
      count: (list.content || list.events || []).length,
      hasRequest: /"request"\s*:/.test(s),
      hasRequestBytes: /"request_bytes"\s*:/.test(s),
      hasRequestStatus: /"request_status"\s*:/.test(s),
      statusVals: [...new Set((s.match(/"request_status"\s*:\s*"([^"]*)"/g) || []))].slice(0, 5),
    };
  } catch (e) { out.search = { ok: false, err: String(e.message).slice(0, 200) }; }
  return out;
}

export default async (ctx, client) => {
  const probe = async (ids) => {
    const r = await client.knowledge.read({ content_ids: ids });
    const s = JSON.stringify(r);
    return {
      ids: ids.length,
      returned: (r.content || []).length,
      hasRequest: /"request"\s*:/.test(s),
      hasRequestStatus: /"request_status"\s*:/.test(s),
      statuses: (s.match(/"request_status"\s*:\s*"[^"]*"/g) || []).slice(0, 4),
    };
  };
  return {
    single: await probe([4821655]),
    multi: await probe([4821655, 4821654, 4821651]),
  };
}
